// src/utils/isSchemaInfoAlreadySorted.ts
var isSchemaInfoAlreadySorted = (schemaInfo) => {
  return schemaInfo.every(
    (relationship, i2) =>
      relationship.childTables == null ||
      relationship.childTables.every(
        (childTable) =>
          schemaInfo.findIndex((r2) => r2.tableName === childTable) > i2,
      ),
  );
};

// src/utils/sortTablesBasedOnHierarchy.ts
var sortTablesBasedOnHierarchy = (schemaInfo) => {
  if (isSchemaInfoAlreadySorted(schemaInfo)) {
    return schemaInfo;
  }
  const sorted = [];
  const visited = new Set();
  const visit = (table) => {
    if (visited.has(table.tableName)) {
      return;
    }
    visited.add(table.tableName);
    if (table.childTables != null) {
      table.childTables.forEach((childTable) => {
        const childRelationship = schemaInfo.find(
          (r2) => r2.tableName === childTable,
        );
        if (childRelationship) {
          visit(childRelationship);
        }
      });
    }
    sorted.push(table);
  };
  schemaInfo.forEach((table) => {
    visit(table);
  });
  return sorted.reverse();
};

