// src/utils/createFolderStructure.ts
import fs2 from 'node:fs';
import path2 from 'node:path';
var createFolderStructure = ({ structure, targetDirectory }) => {
  structure.forEach((item) => {
    if (item.type === 'folder') {
      const folderPath = path2.join(targetDirectory, item.name);
      if (!fs2.existsSync(folderPath)) {
        fs2.mkdirSync(folderPath, { recursive: true });
      }
      createFolderStructure({
        structure: item.children,
        targetDirectory: folderPath,
      });
    }
    if (item.type === 'file') {
      const filePath = path2.join(targetDirectory, item.name);
      if (item.isBinary === true) {
        const binaryData = Buffer.from(item.content, 'base64');
        fs2.writeFileSync(filePath, binaryData);
        return;
      }
      fs2.writeFileSync(filePath, item.content, 'utf-8');
    }
  });
};
var createFolderStructure_default = createFolderStructure;

