var extractTableName = (row, fieldName) => {
  if (row === null || row === undefined || typeof row !== 'object') {
    return null;
  }
  try {
    const value = Reflect.get(row, fieldName);
    if (typeof value !== 'string') {
      return null;
    }
    return value;
  } catch {
    return null;
  }
};
var cherryPickTablesToDelete = async (connectionString, dbType) => {
  try {
    if (dbType === 'postgresql') {
      const query2 = `
        SELECT tablename 
        FROM pg_tables 
        WHERE schemaname = 'public';
      `;
      const result2 = await executePostgreSQL(connectionString, query2);
      if (!Array.isArray(result2)) {
        return '';
      }
      const tablesToDelete2 = [];
      for (const row of result2) {
        const tableName = extractTableName(row, 'tablename');
        if (tableName === null) {
          continue;
        }
        if (IGNORED_TABLES_LARAVEL.includes(tableName)) {
          continue;
        }
        tablesToDelete2.push(`DROP TABLE IF EXISTS "${tableName}" CASCADE;`);
      }
      return tablesToDelete2.join(`
`);
    }
    const { dbName } = extractDBConnectionInfo(connectionString);
    const query = `
      SELECT table_name 
      FROM information_schema.tables 
      WHERE table_schema = '${dbName}';
    `;
    const result = await executeMySQL(connectionString, query);
    if (!Array.isArray(result)) {
      return '';
    }
    const tablesToDelete = [];
    for (const row of result) {
      const tableName = extractTableName(row, 'table_name');
      if (tableName === null) {
        continue;
      }
      if (IGNORED_TABLES_LARAVEL.includes(tableName)) {
        continue;
      }
      tablesToDelete.push(`DROP TABLE IF EXISTS \`${tableName}\`;`);
    }
    return tablesToDelete.join(`
`);
  } catch (error) {
    console.error('Error generating table deletion commands:', error);
    return '';
  }
};
var createOrResetDatabase = async (database, SQLSchema = null) => {
  try {
    let connectionString;
    let extractedDbType;
    if (typeof database === 'string') {
      connectionString = database;
      try {
        const { dbType } = extractDBConnectionInfo(connectionString);
        extractedDbType = dbType;
      } catch (error) {
        return {
          success: false,
          message:
            error instanceof Error
              ? error.message
              : 'Invalid database connection string',
        };
      }
    } else {
      const {
        name,
        user,
        password,
        host,
        port,
        type = 'postgresql',
      } = database;
      if (!name || !user || !host || !port) {
        return {
          success: false,
          message: 'Missing required database connection information',
        };
      }
      if (isNaN(parseInt(port, 10))) {
        return {
          success: false,
          message: 'Database port must be a valid number',
        };
      }
      connectionString = `${type}://${user}:${password}@${host}:${port}/${name}`;
      try {
        const result = extractDBConnectionInfo(connectionString);
        extractedDbType = result.dbType;
      } catch (error) {
        return {
          success: false,
          message:
            error instanceof Error
              ? error.message
              : 'Invalid database connection string',
        };
      }
    }
    if (extractedDbType === 'postgresql') {
      const dropTableCommands = await cherryPickTablesToDelete(
        connectionString,
        extractedDbType,
      );
      const sql2 =
        SQLSchema !== null
          ? `${dropTableCommands}
${SQLSchema}`
          : dropTableCommands;
      if (sql2.trim()) {
        await executePostgreSQL(connectionString, sql2);
      }
    } else {
      const dropTableCommands = await cherryPickTablesToDelete(
        connectionString,
        extractedDbType,
      );
      const sql2 =
        SQLSchema !== null
          ? `${dropTableCommands}
${SQLSchema}`
          : dropTableCommands;
      if (sql2.trim()) {
        await executeMySQL(connectionString, sql2);
      }
    }
    return {
      success: true,
      message:
        SQLSchema !== null
          ? 'Successfully created database and applied schema'
          : 'Successfully reset database',
    };
  } catch (error) {
    console.error('Database operation error:', error);
    return {
      success: false,
      message:
        error instanceof Error
          ? error.message
          : 'Unknown database operation error',
    };
  }
};

