// src/utils/convertLocalFilesToIStructure.ts
function convertLocalFilesToIStructure(directoryPath) {
  if (!directoryPath || !fs4.existsSync(directoryPath)) {
    return [];
  }
  const result = [];
  try {
    const items = fs4.readdirSync(directoryPath);
    for (const item of items) {
      const itemPath = path4.join(directoryPath, item);
      const stats = fs4.statSync(itemPath);
      if (stats.isDirectory()) {
        const folder = {
          name: item,
          type: 'folder',
          children: convertLocalFilesToIStructure(itemPath),
        };
        result.push(folder);
      } else {
        const binary = isBinaryFile(item);
        const content = binary
          ? fs4.readFileSync(itemPath).toString('base64')
          : fs4.readFileSync(itemPath, 'utf-8');
        const file = {
          name: item,
          type: 'file',
          content,
          isBinary: binary,
        };
        result.push(file);
      }
    }
  } catch (error) {
    console.error(`Error reading directory ${directoryPath}:`, error);
  }
  return result;
}
var convertLocalFilesToIStructure_default = convertLocalFilesToIStructure;

